package com.zy.zhangyun;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.concurrent.*;

public class ChooseActivity extends Activity {
  ApiClient api; LinearLayout list; ExecutorService pool=Executors.newSingleThreadExecutor();
  public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(true);setContentView(R.layout.activity_choose);api=new ApiClient(this);list=findViewById(R.id.roleList);load();}
  int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
  Bitmap fallback(String who){int size=180;Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);int[] colors={Color.rgb(180,100,158),Color.rgb(92,139,185),Color.rgb(190,125,99),Color.rgb(97,158,142),Color.rgb(154,113,194),Color.rgb(195,123,83),Color.rgb(91,126,187),Color.rgb(121,158,94),Color.rgb(167,93,133),Color.rgb(91,151,166)};c.drawColor(colors[Math.abs(who.hashCode())%colors.length]);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.WHITE);p.setTextSize(82);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);Paint.FontMetrics fm=p.getFontMetrics();c.drawText(who.substring(0,1),size/2f,size/2f-(fm.ascent+fm.descent)/2f,p);return b;}
  void loadAvatar(ImageView view,String path,String who){pool.execute(()->{Bitmap image=null;try{if(!path.isEmpty()){java.net.URL u=new java.net.URL(api.base()+path);image=BitmapFactory.decodeStream(u.openStream());}}catch(Exception ignored){}final Bitmap shown=image==null?fallback(who):image;runOnUiThread(()->view.setImageBitmap(shown));});}
  void load(){pool.execute(()->{try{JSONArray roles=new JSONObject(api.get("/api/personas")).getJSONArray("personas");runOnUiThread(()->{list.removeAllViews();int[] shades={Color.rgb(173,79,119),Color.rgb(91,105,174),Color.rgb(49,135,130),Color.rgb(187,120,55),Color.rgb(94,144,81),Color.rgb(166,73,101),Color.rgb(69,102,169),Color.rgb(155,102,55),Color.rgb(51,128,119),Color.rgb(142,76,145)};for(int i=0;i<roles.length();i++)try{JSONObject r=roles.getJSONObject(i);String roleName=r.getString("name");LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(14),0,dp(16),0);row.setBackgroundColor(shades[i%shades.length]);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(88));rp.setMargins(0,0,0,dp(12));row.setLayoutParams(rp);TextView dot=new TextView(this);dot.setText("●");dot.setTextColor(Color.rgb(255,220,239));dot.setTextSize(25);row.addView(dot,new LinearLayout.LayoutParams(dp(38),-2));TextView title=new TextView(this);title.setText(roleName);title.setTextSize(21);title.setTextColor(Color.WHITE);title.setGravity(Gravity.CENTER_VERTICAL);row.addView(title,new LinearLayout.LayoutParams(0,-1,1));ImageView pic=new ImageView(this);pic.setScaleType(ImageView.ScaleType.CENTER_CROP);pic.setBackgroundResource(R.drawable.avatar_circle);pic.setClipToOutline(true);row.addView(pic,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView relation=new TextView(this);relation.setText("情感 "+r.optInt("affection",35)+"\n友谊 "+r.optInt("friendship",50));relation.setTextSize(14);relation.setTextColor(Color.rgb(255,226,240));relation.setGravity(Gravity.CENTER_VERTICAL|Gravity.END);LinearLayout.LayoutParams relp=new LinearLayout.LayoutParams(dp(104),-1);relp.setMargins(dp(10),0,0,0);row.addView(relation,relp);final int id=r.getInt("id");row.setOnClickListener(v->{Intent chat=new Intent(this,ChatActivity.class);chat.putExtra("persona_id",id);startActivity(chat);});list.addView(row);loadAvatar(pic,r.optString("avatar",""),roleName);}catch(Exception ignored){}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"角色加载失败，请稍后重试",Toast.LENGTH_LONG).show());}});}
}
